page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state count = 12000
  computed shown = String(Math.round(count)).replace(/\B(?=(\d{3})+(?!\d))/g, ".")
  ref stat
  ref frame
  ref start
  ref observer

  fn reducedMotion() {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches
  }

  fn step(now) {
    let t = Math.min(1, (now - start) / 2000)
    count = 12000 * (1 - Math.pow(1 - t, 3))
    if t < 1 {
      frame = requestAnimationFrame(step)
    }
  }

  fn begin() {
    document.getElementById("features")?.scrollIntoView({ behavior: reducedMotion() ? "auto" : "smooth" })
  }

  mount {
    cleanup {
      observer?.disconnect()
      if frame { cancelAnimationFrame(frame) }
    }
    if reducedMotion() {
      count = 12000
      return
    }
    count = 0
    observer = new IntersectionObserver(entries => {
      if (entries[0].isIntersecting) {
        observer.disconnect()
        start = performance.now()
        frame = requestAnimationFrame(step)
      }
    }, { threshold: 0.5 })
    observer.observe(stat)
  }

  style {
    .page { min-height: 100vh; }
    .hero {
      min-height: 80vh;
      text-align: center;
      color: #fff;
      background: linear-gradient(120deg, #6366f1, #8b5cf6, #ec4899, #06b6d4, #6366f1);
      background-size: 400% 400%;
      animation: nimbus-gradient 20s ease-in-out infinite;
    }
    .hero-title { font-size: clamp(3rem, 10vw, 6rem); margin: 0; letter-spacing: -0.03em; }
    .hero-sub { opacity: 0.9; max-width: 36rem; }
    .features { max-width: 64rem; margin: 0 auto; width: 100%; }
    .stat { font-size: clamp(2.5rem, 8vw, 4.5rem); font-weight: 800; margin: 0; font-variant-numeric: tabular-nums; }
    @keyframes nimbus-gradient {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    @media (prefers-reduced-motion: reduce) {
      .hero { animation: none; background-position: 50% 50%; }
    }
  }

  column class="page" {
    column class="hero" align=center justify=center gap=4 pad=16 {
      title "Nimbus" tag=h1 class="hero-title" animate=rise
      text "La nube ligera para construir sin fricción." large class="hero-sub" animate=fade delay=150
      button "Empezar" primary hover=grow animate=pop delay=300 -> begin()
    }
    grid id="features" class="features" cols=1 md:cols=3 gap=6 pad=8 {
      card reveal pad=6 gap=2 {
        title "Rápido" tag=h3
        text "Carga en milisegundos, incluso en conexiones lentas." muted
      }
      card reveal pad=6 gap=2 {
        title "Simple" tag=h3
        text "Todo lo que necesitás, nada que te sobre." muted
      }
      card reveal pad=6 gap=2 {
        title "Abierto" tag=h3
        text "Código abierto y estándares sin ataduras." muted
      }
    }
    column align=center pad=12 gap=1 {
      title `${shown}+` tag=p class="stat" ref=stat aria-label="12.000+ usuarios"
      text "usuarios" muted
    }
  }
}

