page Home "/" {
  meta title="Nimbus" description="Nimbus: rápido, simple y abierto."

  state users = 0
  ref counter
  ref frame
  ref observer

  computed label = users.toLocaleString("es-AR") + "+"

  fn reducedMotion() {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches
  }

  fn countUp() {
    if reducedMotion() {
      users = 12000
      return
    }
    let target = 12000
    let duration = 2000
    let start = performance.now()
    let step = now => {
      let p = Math.min((now - start) / duration, 1)
      let eased = 1 - Math.pow(1 - p, 3)
      users = Math.round(target * eased)
      if p < 1 {
        frame = requestAnimationFrame(step)
      }
    }
    frame = requestAnimationFrame(step)
  }

  fn start() {
    let el = document.getElementById("features")
    if el {
      el.scrollIntoView({ behavior: reducedMotion() ? "auto" : "smooth" })
    }
  }

  mount {
    observer = new IntersectionObserver(entries => {
      for e in entries {
        if e.isIntersecting {
          countUp()
          observer.disconnect()
        }
      }
    }, { threshold: 0.5 })
    observer.observe(counter)
    cleanup {
      observer.disconnect()
      if frame { cancelAnimationFrame(frame) }
    }
  }

  column gap=0 {
