    .hero-sub {
      color: rgba(255, 255, 255, 0.9);
    }
    .hero-btn {
      font-size: 1.1rem;
      padding: 0.8rem 2rem;
    }
    .cards {
      width: 100%;
      max-width: 1000px;
    }
    .stat-number {
      font-size: clamp(2.5rem, 8vw, 4.5rem);
      font-variant-numeric: tabular-nums;
    }
    @keyframes nimbus-drift {
      0% { background-position: 0% 50%; }
