  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

const features = [
  { title: "Rápido", text: "Cargas instantáneas y respuestas en milisegundos." },
  { title: "Simple", text: "Una interfaz clara que no necesita manual." },
  { title: "Abierto", text: "Código abierto, extensible y sin ataduras." },
];

function FeatureCard({
  title,
  text,
  index,
  visible,
  reduced,
}: {
  title: string;
  text: string;
  index: number;
  visible: boolean;
  reduced: boolean;
}) {
  const shown = reduced || visible;
  return (
    <article
      className={[
        "rounded-2xl border border-white/10 bg-white/5 p-8 shadow-xl backdrop-blur",
        reduced ? "" : "transition-all duration-700 ease-out",
        shown ? "translate-y-0 opacity-100" : "translate-y-8 opacity-0",
      ].join(" ")}
      style={reduced ? undefined : { transitionDelay: `${index * 180}ms` }}
    >
      <h3 className="mb-3 text-2xl font-semibold text-white">{title}</h3>
      <p className="text-slate-300">{text}</p>
    </article>
  );
}

function Counter({ target, reduced }: { target: number; reduced: boolean }) {
  const { ref, inView } = useInView<HTMLDivElement>(0.4);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    const duration = 1500;
    const start = Date.now();
    let done = false;

    const finish = () => {
      if (done) return;
      done = true;
      window.clearInterval(interval);
      window.clearTimeout(timeout);
      setValue(target);
    };

    const interval = window.setInterval(() => {
      const progress = Math.min((Date.now() - start) / duration, 1);
      if (progress >= 0.9) {
        finish();
        return;
      }
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.min(target, Math.round(eased * target)));
    }, 16);

    const timeout = window.setTimeout(finish, duration);

    return () => {
      done = true;
      window.clearInterval(interval);
      window.clearTimeout(timeout);
    };
  }, [inView, reduced, target]);

  const display = `${formatNumber(value)}+`;

  return (
    <div ref={ref} className="text-center">
      <p className="bg-gradient-to-r from-sky-300 via-fuchsia-300 to-amber-200 bg-clip-text text-6xl font-extrabold tabular-nums text-transparent sm:text-7xl">
        {display}
      </p>
      <p className="mt-3 text-lg text-slate-300">usuarios</p>
    </div>
  );
}

