import { createEffect, createSignal, onCleanup } from "solid-js";

export function createReducedMotion() {
  const mq =
    typeof window !== "undefined" && typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : undefined;

  const [reduced, setReduced] = createSignal(mq?.matches ?? false);

  if (mq) {
    const handler = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener("change", handler);
    onCleanup(() => mq.removeEventListener("change", handler));
  }

  return reduced;
}

export function createInView(threshold = 0.2) {
  const [el, setEl] = createSignal<Element>();
  const [inView, setInView] = createSignal(false);

  createEffect(() => {
    const node = el();
    if (!node || inView()) return;

    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold }
    );

    observer.observe(node);
    onCleanup(() => observer.disconnect());
  });

  return { inView, ref: (node: Element) => setEl(node) };
}

