import { createEffect, createSignal, onCleanup, untrack } from "solid-js";
import { createInView, createReducedMotion } from "./useMotion";

const TARGET = 12000;
const DURATION = 2000;
const formatter = new Intl.NumberFormat("es-AR");

export default function Counter() {
  const { inView, ref } = createInView(0.5);
  const reduced = createReducedMotion();
  const [value, setValue] = createSignal(0);

  createEffect(() => {
    if (!inView()) return;
    if (untrack(value) === TARGET) return;

    if (reduced()) {
      setValue(TARGET);
      return;
    }

    let frame = 0;
    const start = performance.now();
    const tick = (now: number) => {
      const progress = Math.min((now - start) / DURATION, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setValue(Math.round(eased * TARGET));
      if (progress < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    onCleanup(() => cancelAnimationFrame(frame));
  });

  return (
    <section class="bg-slate-950 px-6 pb-32 pt-8 text-center text-white">
      <div ref={ref} class="mx-auto max-w-xl">
        <p
