import { createMemo, createSignal, onCleanup, onMount } from "solid-js";
import { observeOnce, prefersReducedMotion } from "./motion";

const TARGET = 12000;
const DURATION = 2000;
const formatter = new Intl.NumberFormat("es-AR");

export default function Counter() {
  const reduced = prefersReducedMotion();
  const [value, setValue] = createSignal(reduced ? TARGET : 0);
  const formatted = createMemo(() => formatter.format(value()));
  let ref: HTMLElement | undefined;
  let frame: number | undefined;
  let safety: ReturnType<typeof setTimeout> | undefined;
  let started = false;

  const animate = () => {
    if (started) return;
    started = true;
    const start = Date.now();

    const step = () => {
      const t = Math.min((Date.now() - start) / DURATION, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      setValue(Math.round(eased * TARGET));
      if (t < 1) {
        frame = requestAnimationFrame(step);
      } else {
        setValue(TARGET);
      }
    };

    if (typeof requestAnimationFrame === "function") {
      frame = requestAnimationFrame(step);
    }
    safety = setTimeout(() => {
      if (frame !== undefined && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame);
      }
      setValue(TARGET);
    }, DURATION + 150);
  };

  onMount(() => {
    if (reduced || !ref) {
      setValue(TARGET);
      return;
    }
    const stop = observeOnce(ref, animate, 0.5);
    onCleanup(() => {
      stop();
      if (frame !== undefined && typeof cancelAnimationFrame === "function") {
        cancelAnimationFrame(frame);
      }
      if (safety) clearTimeout(safety);
    });
  });

  return (
    <section ref={ref} class="mt-32 text-center">
      <p class="sr-only">Más de {formatter.format(TARGET)} usuarios</p>
      <div aria-hidden="true">
        <span class="bg-gradient-to-r from-indigo-400 via-sky-400 to-pink-400 bg-clip-text text-7xl font-extrabold tabular-nums text-transparent sm:text-8xl">
